<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$db->exec("UPDATE support_tickets t JOIN support_sla_policies p ON p.priority=t.priority SET t.due_at=DATE_ADD(t.opened_at,INTERVAL p.resolution_minutes MINUTE) WHERE t.due_at IS NULL AND t.status NOT IN ('resolved','closed')");$q=$db->query("SELECT id,ticket_number,assigned_staff_id,client_id,subject,due_at FROM support_tickets WHERE due_at IS NOT NULL AND due_at<NOW() AND status NOT IN ('resolved','closed')");$n=0;foreach($q as $t){$n++;$x=$db->prepare('INSERT INTO operations_notifications(type,recipient_staff_id,client_id,title,message,reference_type,reference_id) SELECT ?,?,?,?,?,?,? WHERE NOT EXISTS (SELECT 1 FROM operations_notifications WHERE type=? AND reference_type=? AND reference_id=? AND DATE(created_at)=CURDATE())');$x->execute(['sla_breach',$t['assigned_staff_id'],$t['client_id'],'SLA breach: '.$t['ticket_number'],'Ticket '.$t['subject'].' has exceeded its resolution target.','support_ticket',$t['id'],'sla_breach','support_ticket',$t['id']);}echo date('c')." operations automation complete; SLA risks={$n}\n";